#include <cctype>
#include <map>
#include <set>
#include <string>
#include <utility>
#include <vector>

static std::string lower(std::string s)
{
    for (char& c : s) c = static_cast<char>(std::tolower(static_cast<unsigned char>(c)));
    return s;
}

std::string resolveImports(const std::map<std::string, std::set<std::string>>& exportsByDll,
                           const std::vector<std::pair<std::string, std::string>>& imports)
{
    std::map<std::string, const std::set<std::string>*> byLowerName;
    for (const auto& [dll, names] : exportsByDll) byLowerName[lower(dll)] = &names;
    for (const auto& [dll, function] : imports)
    {
        const auto found{ byLowerName.find(lower(dll)) };
        if (found == byLowerName.end()) return "The code execution cannot proceed because " + dll + " was not found.";
        if (!found->second->count(function)) return "The procedure entry point " + function + " could not be located in the dynamic link library " + dll + ".";
    }
    return "";
}

unitTests:
using Exports = std::map<std::string, std::set<std::string>>;
using Imports = std::vector<std::pair<std::string, std::string>>;
const Exports disk{ {"StoneMath.dll", {"stackHeight"}}, {"kernel32.dll", {"WriteFile", "GetStdHandle"}} };
TEST("everything resolves") { CHECK_EQ(resolveImports(disk, Imports{ {"StoneMath.dll", "stackHeight"}, {"KERNEL32.dll", "WriteFile"} }), std::string("")); }
TEST("an older DLL") { CHECK_EQ(resolveImports(disk, Imports{ {"StoneMath.dll", "stackHeight"}, {"StoneMath.dll", "stackWeight"} }), std::string("The procedure entry point stackWeight could not be located in the dynamic link library StoneMath.dll.")); }
TEST("a missing DLL") { CHECK_EQ(resolveImports(disk, Imports{ {"audio.dll", "play"} }), std::string("The code execution cannot proceed because audio.dll was not found.")); }
TEST("the first failure wins") { CHECK_EQ(resolveImports(disk, Imports{ {"kernel32.dll", "Nope"}, {"missing.dll", "x"} }), std::string("The procedure entry point Nope could not be located in the dynamic link library kernel32.dll.")); }
TEST("DLL names ignore case, function names do not") { CHECK_EQ(resolveImports(disk, Imports{ {"stonemath.DLL", "StackHeight"} }), std::string("The procedure entry point StackHeight could not be located in the dynamic link library stonemath.DLL.")); }
TEST("no imports") { CHECK_EQ(resolveImports(disk, Imports{}), std::string("")); }

